layout._cssCustom:mobile_landscape:
.logo-4-list-item li:nth-child(1),
li:nth-child(3) {
  border-right: .5px solid var(--base-trans-10);
	border-bottom: 1px solid var(--base-trans-10); 
}

.logo-4-list-item li:nth-child(2),
li:nth-child(4){
	border-left: .5px solid var(--base-trans-10);
	border-bottom: 1px solid var(--base-trans-10)!important; 
  border-right: 0;
  border-top: 0!important;
}

.logo-4-list-item li:nth-child(5) {
  border: 0;
	border-right: .5px solid var(--base-trans-10); 
}

.logo-4-list-item li:nth-child(6) {
  border: 0;
	border-left: .5px solid var(--base-trans-10); 
}

.logo-4-list-item li div {
	background-size: contain!important;
}

logo-4-list-item.custom_css:
.logo-4-list-item li {
	padding-left: var(--space-xs);
  padding-bottom: 0!important;
}

.logo-4-list-item li:nth-child(1),
li:nth-child(3) {
	border-bottom: .5px solid var(--base-trans-10); 
}


.logo-4-list-item li:nth-child(2) {
	border-right: 1px solid var(--base-trans-10); 
  border-left: 1px solid var(--base-trans-10); 
  border-bottom: .5px solid var(--base-trans-10); 
  border-top: 0;
}

.logo-4-list-item li:nth-child(5) {
	border-top: .5px solid var(--base-trans-10); 
  border-right: 1px solid var(--base-trans-10); 
  border-left: 1px solid var(--base-trans-10); 
  border-bottom: 0; 
}

.logo-4-list-item li:nth-child(4),
li:nth-child(6) {
	border-top: .5px solid var(--base-trans-10); 
  border-bottom: 0; 
}

.logo-4-list-item li div {
	background-size: contain!important;
}
